import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.BF53ZjCA.js";const b=JSON.parse('{"title":"Cabochon & Carving","description":"","frontmatter":{"title":"Cabochon & Carving","cutting":"cabochon-and-carving"},"headers":[],"relativePath":"cutting/cabochon-and-carving.md","filePath":"cutting/cabochon-and-carving.md","lastUpdated":1789230763000}'),i={name:"cutting/cabochon-and-carving.md"};function r(c,e,d,l,s,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="cabochon-carving" tabindex="-1">Cabochon &amp; Carving <a class="header-anchor" href="#cabochon-carving" aria-label="Permalink to &quot;Cabochon &amp; Carving&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>When transparency, inclusions, durability, or an optical phenomenon favors a dome, a stone may be polished en cabochon or carved. This is not an absolute ban on faceting. Cabochons can reveal asterism, chatoyancy, and adularescence; jade and agate are also often carved.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Single / double cabochon: height controls star and cat&#39;s-eye definition.</li><li>Asterism requires oriented polishing — rutile needles parallel to the table.</li><li>Chatoyancy likewise: needle inclusions must align to the dome axis.</li><li>Jade carving (jadeite, nephrite, turquoise) exploits texture and colour zoning.</li><li>Dome height, curvature, and polish together affect the width, brightness, and evenness of the band.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>Star cabochon</td><td>6-ray asterism</td></tr><tr><td>tigers-eye</td><td>Cat&#39;s-eye cabochon</td><td>chatoyancy</td></tr><tr><td>jadeite</td><td>Carved pendant</td><td>imperial jade</td></tr></tbody></table><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',8)])])}const u=a(i,[["render",r]]);export{b as __pageData,u as default};
